return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[静思室]],["permission"]=0,["left"]=[[fb628_43]],["enterable"]=1,["dsc"]=[[楼中弟子犯错后用于静思之地，里头摆放数十张桌椅，有笔墨纸砚。受罚之人需隐忍刑罚惩处后的剧痛，再抄录永夜楼规，若遇罪大恶极之人，以蚂蚁用刑也未可知。期间若发出半点声音，刑罚加倍。]],["fullName"]=[[静思室(fb628_44)]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb628_38]],["canLeave"]=1,["id"]=[[fb628_44]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[诸己阁]],["permission"]=0,["rightDown"]=[[fb628_44]],["fullName"]=[[诸己阁(fb628_38)]],["enterable"]=1,["up"]=[[fb628_31]],["dsc"]=[[永夜楼用于惩罚犯错弟子的地方，名由“反求诸己”。里头放有各色刑具，却无执刑之人。倘若楼中有人犯错，需自责己身，若下手留有余地必会受到更严重的惩罚。]],["down"]=[[fb628_43]],["visible"]=1,["leftDown"]=[[fb628_42]],["dirIndex"]=0,["unit3"]=[[npc10c]],["unit2"]=[[npc09c]],["unit1"]=[[npc08c]],["canLeave"]=1,["id"]=[[fb628_38]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_40]],["connectPoint"]=0,["name"]=[[牢房]],["permission"]=0,["enterable"]=1,["dsc"]=[[一间漆黑的牢房，里头只有一个很小的气窗，门上的小窗用来递送水食。除了关押的囚犯之外，牢房内不会再有其他，即便是老鼠。永夜楼惩罚犯人意在“生死不能”，长期幽闭远比刑罚疼痛来得更可怕。]],["fullName"]=[[牢房(fb628_39)]],["visible"]=1,["unit4"]=[[npc10b]],["dirIndex"]=0,["unit3"]=[[npc09b]],["unit2"]=[[npc08b]],["unit1"]=[[npc07g]],["canLeave"]=1,["id"]=[[fb628_39]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[牢房]],["permission"]=0,["enterable"]=1,["up"]=[[fb628_40]],["dsc"]=[[一间漆黑的牢房，里头只有一个很小的气窗，门上的小窗用来递送水食。除了关押的囚犯之外，牢房内不会再有其他，即便是老鼠。永夜楼惩罚犯人意在“生死不能”，长期幽闭远比刑罚疼痛来得更可怕。]],["fullName"]=[[牢房(fb628_45)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc07h]],["canLeave"]=1,["id"]=[[fb628_45]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_33]],["connectPoint"]=0,["name"]=[[海蜃阁]],["permission"]=0,["left"]=[[fb628_31]],["enterable"]=1,["dsc"]=[[“世如海蜃楼”，此阁由现任永夜楼主所题。阁内两侧建有回旋长梯，阁顶半敞，上观日月星宿，下看藤木古植。后阁的单间则放有古玩摆设、稀奇物件，乃至神剑宝刀也有不少。]],["fullName"]=[[海蜃阁(fb628_32)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc03]],["ca