ight"]=[[fb628_20]],["connectPoint"]=0,["name"]=[[于寂堂]],["permission"]=0,["left"]=[[fb628_18]],["fullName"]=[[于寂堂(fb628_19)]],["enterable"]=1,["up"]=[[fb628_08]],["dsc"]=[[永夜楼的正堂，专门用来招待贵客，亦或是商议要事。堂前匾额乃是由上任永夜楼主所题，意在“同归于寂”，若映衬永夜楼中刺客一生，再贴切不过。]],["down"]=[[fb628_31]],["visible"]=1,["leftDown"]=[[fb628_30]],["dirIndex"]=0,["leftUp"]=[[fb628_07]],["canLeave"]=1,["id"]=[[fb628_19]],["mapHide"]=0},{["operations"]={},["unit1"]=[[npc08e]],["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[火鸽房]],["permission"]=0,["left"]=[[fb628_28]],["enterable"]=1,["dsc"]=[[永夜楼专门豢养火鸽的地方，周围建造了无数大小相同的鸽笼，每一只火鸽都有其编号。火鸽其实与寻常白鸽无异，只是脚上绘有烈火图纹，专用于和永夜楼的线人联络，以便获取刺杀信息。]],["fullName"]=[[火鸽房(fb628_29)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10e]],["unit2"]=[[npc09e]],["leftUp"]=[[fb628_21]],["canLeave"]=1,["id"]=[[fb628_29]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb628_21]],["right"]=[[fb628_29]],["connectPoint"]=0,["name"]=[[内堂]],["permission"]=0,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[逐火堂内堂，里面藏放着自第一代永夜楼主起的所有刺杀账目，亦不知探取了多少江湖人的秘密。自然，这些账目从不轻易示人，即便深处内堂，看到的也只是寻常摆设。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[内堂(fb628_28)]],["canLeave"]=1,["id"]=[[fb628_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_26]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=0,["left"]=[[fb628_24]],["enterable"]=1,["up"]=[[fb628_14]],["dsc"]=[[绿荫遮蔽的走廊，廊下挂着很多小巧的铃铛，风吹时相互碰撞发出清脆的声响回荡在空旷的走廊中。又因四周寂寥，常常让人顿生寒意。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb628_25)]],["canLeave"]=1,["id"]=[[fb628_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_25]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=0,["left"]=[[fb628_23]],["enterable"]=1,["up"]=[[fb628_13]],["dsc"]=[[绿荫遮蔽的走廊，廊下挂着很多小巧的铃铛，风吹时相互碰撞发出清脆的声响回荡在空旷的走廊中。又因四周寂寥，常常让人顿生寒意。]],["down"]=[[fb628_35]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb628_24)]],["canLeave"]=1,["id"]=[[fb628_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[寒更承夜楼]],["permission"]=0,["left"]=[[fb628_26]],["fullName"]=[[寒更承夜楼(fb628_27)]],["enterable"]=1,["up"]=[[fb628_15]],["dsc"]=[[骆宾王有诗，“寒更承夜永，凉景向秋澄”。这是永夜楼的主楼，高七层，顶楼可眺望永夜楼的每个角落。听闻自四层而上，收纳着天下武林秘籍，乃是世人梦寐以求之地。下三层则设武场茶居，可谓样样俱全。]],["down"]=[[fb628_37]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc01]],["canLeave"]=1,["id"]=[[fb628_27]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_27]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=0,["left"]=[[fb628_25]],["enterable"]=1,["dsc"]=[[绿荫遮蔽的走廊，廊下挂着很多小巧的铃铛，风吹时相互碰撞发出清脆的声响回荡在空旷的走廊中。又因四周寂寥，常常让人顿生寒意。]],["fullName"]=[[走廊(fb628_26)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10i]],["unit2"]=[[npc09i]],["unit1"]=[[npc08i]],["canLeave"]=1,["id"]=[[fb628_26]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_22]],["connectPoint"]=0,["name"]=[[逐火堂]],["unit4"]=[[25cyshopyongye]],["permission"]=0,["left"]=[[fb628_20]],["rightDown"]=[[fb628_29]],["enterable"]=1,["dsc"]=[[逐火堂乃是永夜楼搜集消息、打探情报、分发刺杀任务之处。堂中设有数千个木柜抽屉，里头放有契约及定金，有专人登记造册。永夜楼来者不拒，只要付出相应价值的赎金就能结成一笔买卖。]],["fullName"]=[[逐火堂(fb628_21)]],["visible"]=1,["leftDown"]=[[fb628_28]],["dirIndex"]=0,["unit3"]=[[npc10h]],["unit2"]=[[npc09h]],["unit1"]=[[npc08h]],["canLeave"]=1,["id"]=[[fb628_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_21]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=0,["left"]=[[fb628_19]],["enterable"]=1,["dsc"]=[[绿荫遮蔽的走廊，廊下挂着很多小巧的铃铛，风吹时相互碰撞发出清脆的声响回荡在空旷的走廊中。又因四周寂寥，常常让人顿生寒意。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb628_20)]],["canLeave"]=1,["id"]=[[fb628_20]],["mapHide"]=0},{["operations"]={},["right"]=[[fb628_24]],["connectPoint"]=0,["enterable"]=1,["visible"]=1,["id"]=[[fb628_23]],["dsc"]=[[千金堂收藏着历代永夜楼所藏的珍宝奇货，堂内正中用纯金打造了一座七宝华楼，象征着代代永夜。且凡楼中之人，若有所需皆可到此求取，不过需要完成千金楼单独指派的任务。]],["permission"]=0,["fullName"]=[[千金堂(fb628_23)]],["mapHide"]=0,["stepMusic"]=[[jiaobu]],["canLeave"]=1,["name"]=[[千金堂]],["up"]=[[fb628_12]],["dirIndex"]=0,["unit3"]=[[npc04]],["unit2"]=[[npc08f]],["unit1"]=[[shengwang27]],["unit4"]=[[npc09f]],["unit6"]=[[22yongyecynpc]],["unit5"]=[[npc10f]],["left"]=[[fb628_22]]},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_23]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=0,["left"]=[[fb628_21]],["enterable"]=1,["dsc"]=[[绿荫遮蔽的走廊，廊下挂着很多小巧的铃铛，风吹时相互碰撞发出清脆的声响回荡在空旷的走廊中。又因四周寂寥，常常让人顿生寒意。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb628_22)]],["canLeave"]=1,["id"]=[[fb628_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=0,["rightDown"]=[[fb628_19]],["enterable"]=1,["dsc"]=[[绿荫遮蔽的走廊，廊下挂着很多小巧的铃铛，风吹时相互碰撞发出清脆的声响回荡在空旷的走廊中。又因四周寂寥，常常让人顿生寒意。]],["visible"]=1,["leftDown"]=[[fb628_17]],["dirIndex"]=0,["fullName"]=[[走廊(fb628_07)]],["canLeave"]=1,["id"]=[[fb628_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[揽夜亭]],["permission"]=0,["enterable"]=1,["dsc"]=[[揽夜亭四周被古藤树遮蔽，根本无法看清夜色如何，“揽夜”二字只是初代永夜楼主昔年创下揽夜神掌时兴之所题。亭前小路有一排石灯长燃，古藤树上绑缚着一个绳索腐烂的秋千，附近空旷开阔，适宜练武。]],["down"]=[[fb628_15]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[揽夜亭(fb628_06)]],["canLeave"]=1,["id"]=[[fb628_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[阴晦小路]],["permission"]=0,["enterable"]=1,["up"]=[[fb628_04]],["dsc"]=[[藏在石林中的隐蔽小路，小路顶端层层叠嶂，像是被一片片乌云所遮掩，阴晦不已。不时会有阵阵寒风从四面八方的石缝中吹来，发出古怪的声音，如同哭泣一般。]],["down"]=[[fb628_08]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[阴晦小路(fb628_05)]],["canLeave"]=1,["id"]=[[fb628_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[佚名堂]],["permission"]=0,["fullName"]=[[佚名堂(fb628_04)]],["enterable"]=1,["up"]=[[fb628_01]],["dsc"]=[[佚名堂专门负责训练杀手，堂中没有任何的摆设，只是挂满数千木牌，上面刻着的都是尚未成为永夜楼真正杀手之人的名字，若在训练中不被看重，木牌被毁，则下场凄惨。只有走出此堂，取得代称，方能真正成为杀手。]],["down"]=[[fb628_05]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10a]],["unit2"]=[[npc09a]],["unit1"]=[[npc08a]],["canLeave"]=1,["id"]=[[fb628_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[密林]],["permission"]=0,["left"]=[[fb628_02]],["enterable"]=1,["dsc"]=[[不知通向何方的密林，林中原本没有路，而是被踩出了一条小道，道路周围插着数百把新旧不一的刀剑兵刃，不知是何人留下。偶然能听到几声乌鸦的鸣叫，让人不寒而栗。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[密林(fb628_03)]],["canLeave"]=1,["id"]=[[fb628_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_03]],["connectPoint"]=0,["name"]=[[密林]],["permission"]=0,["left"]=[[fb628_01]],["enterable"]=1,["dsc"]=[[不知通向何方的密林，林中原本没有路，而是被踩出了一条小道，道路周围插着数百把新旧不一的刀剑兵刃，不知是何人留下。偶然能听到几声乌鸦的鸣叫，让人不寒而栗。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[密林(fb628_02)]],["canLeave"]=1,["id"]=[[fb628_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_02]],["connectPoint"]=0,["name"]=[[巨石门]],["permission"]=0,["enterable"]=1,["dsc"]=[[前方有一道巨大的石门，两侧巨石堆积成山，且到处都爬满了青苔，但奇怪的是，道路中间十分干净，连一片落叶都没有，似乎常常有人在此清扫。]],["down"]=[[fb628_04]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[巨石门(fb628_01)]],["canLeave"]=1,["id"]=[[fb628_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb628_44]],["connectPoint"]=0,["name"]=[[刑堂]],["permission"]=0,["left"]=[[fb628_42]],["enterable"]=1,["up"]=[[fb628_38]],["dsc"]=[[堂内有数百种酷刑，弟子犯错全凭自身选择，若心存侥幸故意宽纵自身，则会受到更严酷的惩罚。刑堂内还有数十木架，专门用于审问那些背叛永夜楼之人亦或是其他囚犯，周围血迹斑斑，可见惨状。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[刑堂(fb628_43)]],["canLeave"]=1,["id"]=[[fb628_43]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb628_38]],["right"]=[[fb628_43]],["connectPoint"]=0,["name"]=[[静思室]],["permission"]=0,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[楼中弟子犯错后用于静思之地，里头摆放数十张桌椅，有笔墨纸砚。受罚之人需隐忍刑罚惩处后的剧痛，再抄录永夜楼规，若遇罪大恶极之人，以蚂蚁用刑也未可知。期间若发出半点声音，刑罚加倍。]],["fullName"]=[[静思室(fb628_42)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc07f]],["canLeave"]=1,["id"]=[[fb628_42]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[牢房]],["permission"]=0,["left"]=[[fb628_40]],["enterable"]=1,["dsc"]=[[一间漆黑的牢房，里头只有一个很小的气窗，门上的小窗用来递送水食。除了关押的囚犯之外，牢房内不会再有其他，即便是老鼠。永夜楼惩罚犯人意在“生死不能”，长期幽闭远比刑罚疼痛来得更可怕。]],["visible"]=1,["dir